∀ {V : Type u_1} [inst : DecidableEq.{u_1 + 1} V] {E : V → V → Prop}
  {motive : (a : Finset.{u_1} V) → (a_1 : V) → GraphPotential.Rooted.{u_1} E a a_1 → Prop} {S T : Finset.{u_1} V}
  {z : V} (a : GraphPotential.Rooted.{u_1} E S z) (a_1 : GraphPotential.Rooted.{u_1} E T z)
  (a_2 : ∀ (x : V), Membership.mem.{u_1, u_1} S x → Membership.mem.{u_1, u_1} T x → Eq.{u_1 + 1} x z),
  GraphPotential.Rooted.below.{u_1} a →
    motive S z a → GraphPotential.Rooted.below.{u_1} a_1 → motive T z a_1 → GraphPotential.Rooted.below.{u_1} ⋯

